#include "help_topics.h"
typedef struct {const char *title,*text[TL_HELP_LEVEL_COUNT];} Topic;
static const char *const levels[]={"Novice — iniciante","Intermediate — intermediário","Expert — especialista"};
static const Topic topics[]={
 {"Primeiros passos",{
  "Uma receita reúne as medidas e regras de cores que você quer experimentar. Ela é uma proposta: salvar uma receita não instala um tema.\n\nEscolha a família, selecione os controles visíveis, altere um ajuste e pressione Atualizar. Compare o controle real com a referência Motif. Leia as medidas nativas antes de concluir que os tamanhos são iguais.\n\nSalvar guarda o projeto; Exportar prepara uma proposta privada. A instalação no desktop é uma etapa separada.",
  "Trabalhe em uma receita por família. Selecione o controle e seu estado, ajuste a proposta e use Atualizar para aplicar à prévia. Compare pedido, alocação e escala efetiva; conserve a proveniência da referência.\n\nProjeto salvo, proposta gerada e cena aplicada são resultados diferentes. Exportação privada não instala o tema.",
  "Fluxo: receita por família → geração privada → cena nativa → medidas/comparação → exportação revisável. Salvar/gerar não comprova aplicação, suporte ou fidelidade. Instalação é separada."}},
 {"Família e referência Motif",{
  "Família significa o conjunto de controles de uma plataforma, como GTK2 ou Qt6. A prévia usa essa plataforma quando seu runtime está disponível; uma imagem não a substitui.\n\nA referência Motif usa controles reais da biblioteca instalada. Ela ajuda na comparação, mas não prova os padrões exatos do Domain/OS SR10.4. A imagem histórica e as medidas da VM são evidências separadas.\n\nSe o painel informa que uma tradução está pendente, a receita pode existir sem funcionar naquela plataforma.",
  "Cada família mantém receita própria e status de suporte. O canvas nativo e a prévia separada precisam do runtime e do adaptador correspondente; disponibilidade de runtime não significa cobertura de todos os controles.\n\nMotif instalado é referência operacional. Somente evidência da VM SR10.4/HP VUE 2.01 sustenta equivalência histórica; não trate defaults de outra biblioteca como medidas da VM.",
  "Separar runtime, cobertura do adaptador, receita e prova histórica. Motif local não certifica defaults SR10.4. Nível Motif usa Scale somente leitura, não ProgressBar nativa."}},
 {"Geometria, escala e fonte",{
  "px significa pixel. Largura e altura pedem o tamanho do controle; zero deixa o toolkit escolher. A medida nativa mostra o tamanho que ele realmente recebeu, que pode ser maior devido a um mínimo.\n\nBarra é a espessura transversal. Cursor é a peça que você arrasta. Seu comprimento depende do conteúdo; não copie o comprimento de uma janela vazia para todas as janelas.\n\nFonte é o tamanho solicitado. Confira a fonte efetiva e a escala nas medidas: dimensão igual não garante desenho igual.",
  "Pedido, mínimo, natural e alocação são métricas distintas. Compare em pixels físicos usando a escala efetiva. Espessura transversal e comprimento longitudinal não são intercambiáveis.\n\nRelevo e margens precisam caber na peça. Conteúdo/Barra fica fora da espessura da barra; Moldura pertence ao encaixe do conteúdo. Fonte solicitada pode ter substituição: consulte as métricas.",
  "Comparar pedido/mínimo/natural/alocação com escala efetiva. Zero delega o eixo; tamanho personalizado não implica default histórico. Separar espessura, comprimento, relevo, gap e fonte efetiva."}},
 {"Posição, dimensão e âncora",{
  "X desloca o controle para os lados; Y desloca para cima ou para baixo. Essas posições são relativas à área de montagem, não à tela inteira.\n\nAo alterar o comprimento de uma barra, Início fixo mantém sua primeira extremidade no lugar. Fim fixo mantém a outra. Essa opção só funciona nas famílias indicadas pela interface e pode exigir uma prévia atualizada.\n\nA posição da proposta e a posição medida no controle nativo devem ser comparadas antes de avaliar alinhamento.",
  "Posições são locais ao canvas. A âncora usa a extensão nativa aplicada; mudanças pendentes de tamanho/geometria impedem uma troca confiável. Atualize a cena antes de trocar a extremidade fixa.\n\nO eixo transversal de uma barra pode ficar travado no editor de dimensão: ajuste a receita da peça para alterar espessura. Não confunda a medida do grupo de opções com a de um membro.",
  "X/Y locais, âncora longitudinal por extensão nativa. Troca pode ser recusada com cena desatualizada ou família sem suporte. Grupo e membro têm alocações distintas; não inferir defaults."}},
 {"Papéis de cores e contraste",{
  "Um papel é uma função da cor, como fundo do botão ou texto da janela. Em vez de gravar um azul fixo, a receita pede essa função ao esquema KDE escolhido.\n\nO esquema de teste afeta somente os controles da prévia. As ferramentas e esta ajuda acompanham a paleta da interface. Luz, sombra e trilho são derivados das cores pelos fatores; esses fatores não têm unidade.\n\nConfira se texto e fundo continuam legíveis em temas claros, escuros e amarelos. Amostrar um pixel não muda automaticamente os papéis.",
  "Mapeie papéis correspondentes de face/texto, conteúdo e seleção. Fatores de luz/sombra/trilho são adimensionais; RGB final deve depender da paleta. Esquema de teste não altera o desktop.\n\nConfira contraste por estado, não apenas normal. O sufixo breeze em nomes de papéis GTK não fixa aparência Breeze. No projeto DomainOS, somente LED/Pager têm exceção de sinal com proteção de contraste.",
  "Papéis KDE atuais → face/texto/conteúdo/seleção → luz/sombra/trilho derivados. Sem RGB final estático. breeze é nome de integração, não paleta fixa. Exceções: LED/Pager com contraste protegido."}},
 {"Estados e relevo das peças",{
  "Normal, pressionado, desabilitado e sem foco são situações diferentes. Pressionado é o instante em que você segura o botão; selecionado pode continuar ligado depois de soltar.\n\nSelecione a peça que quer ajustar: seta, botão da seta, trilho, cursor ou encaixe. Relevo é a borda de luz e sombra que dá aparência elevada ou rebaixada. -1 em uma medida da peça significa herdar a regra da família.\n\nO seletor edita a receita. Alguns estados só podem ser vistos ao interagir com o controle real; consulte o suporte indicado.",
  "As receitas de seta, botão, trilho, cursor e encaixe são independentes. Herança -1 vale nos parâmetros numéricos que a indicam. Pressão momentânea e seleção persistente têm contratos distintos.\n\nEditar um estado não necessariamente o força na prévia. GtkRange pode eliminar foco ou pressão de nós internos; a interface declara o suporte por peça/família. Compare a interação nativa, não só o seletor.",
  "Separar receita de estado e estado nativo observado. Pressão ≠ seleção persistente. Peças têm geometria/relevo próprios; -1 herda onde declarado. Suporte a foco/hover/backdrop depende do consumidor."}},
 {"Categorias e montagem",{
  "Marcar uma categoria permite ver seus controles. Na lista, você também escolhe quais controles dessa categoria devem aparecer. Ocultar um item não apaga sua receita nem posição.\n\nA montagem é a área de comparação. Na prévia que anuncia esse suporte, Ctrl+clique seleciona e Ctrl+arraste move um controle; sem Ctrl, você testa o comportamento nativo.\n\nUm controle não traduzido deve ser informado como pendente. Não avalie uma imagem ou controle de outro toolkit como se fosse a prévia pedida.",
  "Visibilidade combina máscara da categoria e do controle; posição/receita continuam salvas. Use a interação anunciada pelo canvas: gestos de edição e interação normal têm funções diferentes.\n\nA montagem pode ser parcial conforme o adaptador. Controle ausente precisa aparecer no status de suporte, não ser substituído silenciosamente por outra família.",
  "Máscaras categoria∧controle, posições preservadas. Ctrl gestos somente onde implementados. Admissão da cena e cobertura de tradução são verificadas separadamente; sem substituição silenciosa de toolkit."}},
 {"Pipeta e evidência",{
  "A pipeta lê um pixel visível por X11 e registra X/Y em pixels da tela, visual de origem e RGB16 (0–65535) e RGB8 (0–255).\n\nA medida ajuda a comparar uma referência. Ela não transforma automaticamente a receita numa coleção de cores fixas. Para usar uma amostra como entrada de esquema, mantenha essa operação separada dos papéis semânticos dos controles.\n\nWayland pode bloquear a captura de outros clientes. Nesse caso, não invente uma amostra nem declare a captura completa.",
  "Amostra contém coordenadas X/Y da tela em px, visual de origem e RGB16/RGB8 nos respectivos intervalos. Registre qual imagem ou prévia estava sendo medida e sua escala. Não interprete antialiasing ou interpolação como uma nova regra histórica.\n\nA captura via X11 não garante acesso nativo a todos os clientes Wayland. Amostra é evidência/entrada de esquema; não substitui automaticamente os papéis KDE.",
  "Pipeta X11: X/Y em px de tela, RGB16 0–65535, RGB8 0–255, origem e visual. Separar amostra, regra de papel e entrada de esquema. Limites Wayland explícitos; nunca inventar cor ou proveniência."}},
 {"Projeto, histórico e exportação",{
  "O projeto guarda os ajustes e receitas das famílias. Salvar cria um arquivo para continuar depois. Carregar abre outro projeto; confira seu nome e origem antes de trabalhar.\n\nUndo/Redo de texto desfaz a edição de um campo. O histórico do projeto recupera mudanças da receita: são mecanismos diferentes. Um ponto salvo no histórico ajuda a voltar a uma etapa conhecida.\n\nExportar gera uma proposta privada com dependências. Não instala o tema no usuário e não confirma que a aparência foi aprovada.",
  "Separe histórico de campos, histórico do projeto e arquivos exportados. Salvar preserva receitas de outras famílias; ajustes de prévia não devem substituir dados históricos medidos.\n\nAntes de instalar, revise diferenças e dependências da proposta, suporte efetivo e evidência da cena aplicada. Geração/exportação não é aprovação humana nem instalação.",
  "Codec/projeto, histórico de receita e Undo de campo são responsabilidades separadas. Exportação privada conserva proveniência; não equivale a instalação, cena aplicada ou aceite humano."}},
 {"Atualização, prévias e falhas",{
  "Atualizar aplica seus ajustes à prévia. Com atualização automática ligada, a ferramenta espera o intervalo em milissegundos após a última edição para reunir várias mudanças.\n\nMostrar prévia separada abre uma janela nativa adicional; você pode desligá-la sem fechar a montagem. Algumas famílias podem estar indisponíveis.\n\nSe uma prévia falhar, leia o status antes de continuar a comparação. A última cena válida pode permanecer na tela: isso não significa que a proposta nova foi aplicada.",
  "Atualização automática usa debounce: cada edição renova o intervalo. Isso não é duração simulada de uma operação do controle. Acoplada e separada são origens distintas de eventos e métricas.\n\nFalha preserva a última cena válida quando o adaptador suporta a transação; consulte o status aplicado/proposto. Eventos antigos não devem modificar uma nova cena. Runtime disponível não garante tradutor concluído.",
  "Debounce reúne edições; não bloqueia ação real. Origens acoplada/separada e hashes da cena são independentes. Falha/timeout deve preservar editor/projeto e anunciar a proposta não aplicada; cobertura por família."}}
};
const char *tl_help_topic_title(int topic){return topic>=0&&topic<TL_HELP_TOPIC_COUNT?topics[topic].title:0;}
const char *tl_help_level_title(int level){return level>=0&&level<TL_HELP_LEVEL_COUNT?levels[level]:0;}
const char *tl_help_topic_text(int topic,int level){return topic>=0&&topic<TL_HELP_TOPIC_COUNT&&level>=0&&level<TL_HELP_LEVEL_COUNT?topics[topic].text[level]:0;}
